import SwiftUI
import MapKit
import Polyline

struct TrailAnimationView: View {
    @StateObject private var animator = TrailAnimator()

    var body: some View {
        ZStack {
            Map(position: $animator.cameraPosition) {
                MapPolyline(coordinates: animator.currentTrail)
                    .stroke(.blue, style: StrokeStyle(lineWidth: 5, lineCap: .round))
            }
            .mapStyle(.hybrid)
            .ignoresSafeArea()
            .gesture(
                MagnificationGesture()
                    .onChanged { scale in
                        animator.zoomGesture(scale: scale)
                    }
            )

//            VStack {
//                Spacer()
//                Button("▶️ Start Animation") {
//                    animator.startAnimation()
//                }
//                .padding()
//                .background(.ultraThinMaterial)
//                .clipShape(RoundedRectangle(cornerRadius: 12))
//                .padding(.bottom, 40)
//            }
        }
        .onAppear {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.04) {
                animator.startAnimation()
            }
        }
    }
}

#Preview {
    TrailAnimationView()
}



