    init() {
        allcoordinates = decodePolyline(encodeddata)!
        
        coordinates = allcoordinates.enumerated().compactMap { index, coord in
            (index == 0 || index % 5 == 0) ? coord : nil
        }
        
    }

    // -----------------------------------
    // MARK: - Pinch Zoom Handler
    // -----------------------------------
    func zoomGesture(scale: CGFloat) {
        // convert gesture scale → zoom distance
        let delta = (1 / scale)

        zoom *= delta

        // clamp zoom
        zoom = min(maxZoom, max(minZoom, zoom))
    }

    // -----------------------------------
    // MARK: Animation
    // -----------------------------------
    func startAnimation() {
        guard !isAnimating else { return }
        isAnimating = true
        index = 0
        currentTrail = [coordinates.first!]

        animateNextPoint()
    }

    private func animateNextPoint() {
        guard index < coordinates.count else {
            isAnimating = false
            return
        }

        let coord = coordinates[index]

        currentTrail.append(coord)

        let heading = computeHeading()

        // Camera follows zoom
        if index % 10 == 0 {
            withAnimation(.linear(duration: stepDuration)) {
                cameraPosition = .camera(
                    MapCamera(
                        centerCoordinate: coord,
                        distance: zoom,     // ← ← ← uses live zoom
                        heading: heading,
                        pitch: 70
                    )
                )
            }
        }

        index += 1

        DispatchQueue.main.asyncAfter(deadline: .now() + stepDuration) {
            self.animateNextPoint()
        }
    }

    private func computeHeading() -> CLLocationDirection {
        if index >= coordinates.count - 1 { return 0 }
        return bearing(from: coordinates[index], to: coordinates[index + 1])
    }

    private func bearing(from: CLLocationCoordinate2D, to: CLLocationCoordinate2D) -> CLLocationDirection {
        let lat1 = from.latitude * .pi / 180
        let lon1 = from.longitude * .pi / 180
        let lat2 = to.latitude * .pi / 180
        let lon2 = to.longitude * .pi / 180
        let dLon = lon2 - lon1

        let y = sin(dLon) * cos(lat2)
        let x = cos(lat1) * sin(lat2) - sin(lat1) * cos(lat2) * cos(dLon)

        let heading = atan2(y, x)
        return heading * 180 / .pi
    }
}
